package main

import (
	"context"
	"errors"
	"fmt"
	"log"

	inorbit "github.com/inorbithr/sdk/go"
	"github.com/inorbithr/sdk/go/public"
)

func main() {
	if err := run(context.Background()); err != nil {
		var apiErr *inorbit.APIError
		if errors.As(err, &apiErr) {
			log.Fatalf("%s: %s (request id %s)", apiErr.Code, apiErr.Problem, apiErr.Raw.RequestID)
		}
		log.Fatal(err)
	}
}

func run(ctx context.Context) error {
	// Reads INORBIT_TOKEN, or INORBIT_KEY_ID and INORBIT_KEY_SECRET.
	api, err := public.FromEnv()
	if err != nil {
		return err
	}
	res, err := api.Accounts().GetMe(ctx)
	if err != nil {
		return err
	}
	fmt.Printf("%+v\n", res.Value)
	return nil
}

