use inorbithr::public::{AccountsListUnitCategoriesParams, Surface as _};
use inorbithr::{Client, Error};

#[tokio::main]
async fn main() {
    if let Err(err) = run().await {
        match err {
            Error::Api(e) => eprintln!("{}: {} (request id {})", e.code, e.message, e.raw.request_id),
