use inorbithr::public::{RadarListItemsParams, Surface as _};
use inorbithr::{Client, Error};

#[tokio::main]
async fn main() {
    if let Err(err) = run().await {
        match err {
            Error::Api(e) => eprintln!("{}: {} (request id {})", e.code, e.message, e.raw.request_id),
            e => eprintln!("{e}"),
        }
        std::process::exit(1);
    }
}

async fn run() -> Result<(), Error> {
    // Reads INORBIT_TOKEN, or INORBIT_KEY_ID and INORBIT_KEY_SECRET.
    let api: Client = Client::from_env()?;
    let params = RadarListItemsParams::default();
    let radar = api.radar();
    let mut pages = radar.all_list_items(&params);
    while let Some(item) = pages.next().await {
        println!("{:?}", item?);
    }
    Ok(())
}

